const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtDate = v => { const d = new Date(v); return isNaN(d) ? '—' : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }); };
const ymd = d => d.toISOString().slice(0, 10);
const addMonths = (v, m) => { const d = new Date(v); if (isNaN(d)) return null; const day = d.getUTCDate(); const r = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + Number(m), 1)); const last = new Date(Date.UTC(r.getUTCFullYear(), r.getUTCMonth() + 1, 0)).getUTCDate(); r.setUTCDate(Math.min(day, last)); return r; };
const button = (url, label) => `<p style="margin:20px 0"><a href="${esc(url)}" style="background:#0f766e;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold">${esc(label)}</a></p>`;
const shell = (s, inner) => `<div style="font-family:Arial,sans-serif;max-width:620px;color:#111827;line-height:1.5">${inner}<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0"><p style="color:#6b7280;font-size:12px">${esc(s.dealer_name)} · ${esc(s.dealer_address)} · ${esc(s.dealer_phone)}</p></div>`;

// ===== Category rules — edit to match your brands (months / km / INR) =====
const RULES = {
  'Car':             { warranty: 36, first: 1,  interval: 12, km: 10000, free: 3, service_value: 6000, ext_value: 15000 },
  'Two Wheeler':     { warranty: 24, first: 1,  interval: 4,  km: 3000,  free: 3, service_value: 900,  ext_value: 2500 },
  'Air Conditioner': { warranty: 12, first: 6,  interval: 6,  km: 0,     free: 2, service_value: 800,  ext_value: 3500 },
  'Refrigerator':    { warranty: 12, first: 12, interval: 12, km: 0,     free: 0, service_value: 600,  ext_value: 2500 },
  'Washing Machine': { warranty: 24, first: 12, interval: 12, km: 0,     free: 1, service_value: 700,  ext_value: 2500 },
  'Water Purifier':  { warranty: 12, first: 4,  interval: 4,  km: 0,     free: 3, service_value: 1200, ext_value: 3000 },
  'Television':      { warranty: 12, first: 0,  interval: 0,  km: 0,     free: 0, service_value: 0,    ext_value: 2500 },
  'Other Appliance': { warranty: 12, first: 12, interval: 12, km: 0,     free: 0, service_value: 500,  ext_value: 2000 },
};
const out = [];
for (const item of $input.all()) {
  const j = item.json, s = j;
  const src = (j.body && typeof j.body === 'object') ? j.body : j;
  const pick = keys => { for (const k of keys) if (src[k] !== undefined && src[k] !== null && src[k] !== '') return src[k]; return ''; };
  const name = String(pick(['customer_name', 'Full Name', 'name'])).trim();
  const serial = String(pick(['serial_number', 'Serial / VIN / Chassis Number', 'vin', 'serial'])).trim().toUpperCase();
  if (!name || !serial) continue;
  let phone = String(pick(['phone', 'Mobile Number', 'mobile'])).replace(/\D/g, '');
  if (phone.length === 10) phone = String(s.default_country_code || '91') + phone;
  const catRaw = String(pick(['category', 'Product Category']) || 'Other Appliance');
  const category = Object.keys(RULES).find(k => k.toLowerCase() === catRaw.toLowerCase()) || 'Other Appliance';
  const R = RULES[category];
  let purchase = new Date(pick(['purchase_date', 'Purchase Date']));
  if (isNaN(purchase)) purchase = new Date();
  const extRaw = String(pick(['extended_warranty_months', 'Extended Warranty']) || '0');
  const ext = /year/i.test(extRaw) ? (parseInt(extRaw) || 0) * 12 : (parseInt(extRaw) || 0);
  const wMonths = Number(pick(['warranty_months'])) || R.warranty;
  const interval = Number(pick(['service_interval_months'])) || R.interval;
  const firstGap = R.first || interval;
  const now = new Date();
  // Late registrations: roll the first due service forward to the next upcoming one
  let nextService = interval ? addMonths(purchase, firstGap) : null, svcNo = 1;
  while (nextService && nextService < new Date(now.getTime() - 7 * 864e5)) { nextService = addMonths(nextService, interval); svcNo++; }
  out.push({ json: {
    registration_id: `WR-${ymd(now).slice(2).replace(/-/g, '')}-${Math.random().toString(36).slice(2, 6).toUpperCase()}`,
    registered_at: now.toISOString(),
    source: j.body ? 'DMS/POS webhook' : 'Registration form',
    status: 'Active',
    customer_name: name,
    first_name: name.split(' ')[0],
    last_name: name.split(' ').slice(1).join(' '),
    phone: phone ? `+${phone}` : '',
    email: String(pick(['email', 'Email'])).trim().toLowerCase(),
    dealer_branch: String(pick(['dealer_branch', 'branch'])),
    category, brand: String(pick(['brand', 'Brand'])), model: String(pick(['model', 'Model'])),
    serial_number: serial,
    vehicle_reg_no: String(pick(['vehicle_reg_no', 'Vehicle Registration Number'])).replace(/\s+/g, '').toUpperCase(),
    invoice_number: String(pick(['invoice_number', 'Invoice Number'])),
    purchase_date: ymd(purchase),
    warranty_months: wMonths, extended_warranty_months: ext,
    warranty_end: ymd(addMonths(purchase, wMonths + ext)),
    service_interval_months: interval, service_interval_km: R.km, free_services_total: R.free,
    services_done: 0, last_service_date: '', last_odometer_km: String(pick(['odometer_km', 'Current Odometer (km)']) || ''),
    next_service_number: interval ? svcNo : '', next_service_date: nextService ? ymd(nextService) : '',
    first_service_months: firstGap,
    est_service_value: R.service_value, est_extended_value: R.ext_value,
  }});
}
return out;

const existing = new Set($('Get Existing Registrations').all().map(i => String(i.json.serial_number || '').toUpperCase()).filter(Boolean));
const seen = new Set();
return $('Normalize Registration Data').all().filter(i => {
  const k = i.json.serial_number;
  if (existing.has(k) || seen.has(k)) return false;
  seen.add(k); return true;
}).map(i => ({ json: i.json }));

const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtDate = v => { const d = new Date(v); return isNaN(d) ? '—' : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }); };
const ymd = d => d.toISOString().slice(0, 10);
const addMonths = (v, m) => { const d = new Date(v); if (isNaN(d)) return null; const day = d.getUTCDate(); const r = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + Number(m), 1)); const last = new Date(Date.UTC(r.getUTCFullYear(), r.getUTCMonth() + 1, 0)).getUTCDate(); r.setUTCDate(Math.min(day, last)); return r; };
const button = (url, label) => `<p style="margin:20px 0"><a href="${esc(url)}" style="background:#0f766e;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold">${esc(label)}</a></p>`;
const shell = (s, inner) => `<div style="font-family:Arial,sans-serif;max-width:620px;color:#111827;line-height:1.5">${inner}<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0"><p style="color:#6b7280;font-size:12px">${esc(s.dealer_name)} · ${esc(s.dealer_address)} · ${esc(s.dealer_phone)}</p></div>`;

const s = $('Set Registration Config').first().json;
const regs = $('Skip Duplicate Serials').all();
const cols = ["registration_id", "registered_at", "source", "status", "customer_name", "phone", "email", "ghl_contact_id", "dealer_branch", "category", "brand", "model", "serial_number", "vehicle_reg_no", "invoice_number", "purchase_date", "warranty_months", "extended_warranty_months", "warranty_end", "service_interval_months", "service_interval_km", "free_services_total", "services_done", "last_service_date", "last_odometer_km", "next_service_number", "next_service_date", "service_reminder_stage", "warranty_reminder_stage", "service_opportunity_id", "warranty_opportunity_id", "est_service_value", "est_extended_value", "lifetime_service_revenue"];
return $input.all().map((item, i) => {
  const r = { ...regs[i].json, ghl_contact_id: item.json.contact?.id || item.json.id || '', service_reminder_stage: '', warranty_reminder_stage: '',
              service_opportunity_id: '', warranty_opportunity_id: '', lifetime_service_revenue: 0 };
  const row = {}; cols.forEach(k => row[k] = r[k] ?? '');
  const product = `${r.brand} ${r.model}`.trim();
  const schedule = [];
  if (r.service_interval_months) for (let n = 0; n < 3; n++) {
    const d = addMonths(r.purchase_date, Number(r.first_service_months) + n * Number(r.service_interval_months));
    schedule.push(`<tr><td style="padding:4px 12px 4px 0">Service #${n + 1}${n + 1 <= r.free_services_total ? ' <b style="color:#0f766e">(FREE)</b>' : ''}</td><td>${fmtDate(d)}${r.service_interval_km ? ` or ${(r.service_interval_km * (n + 1)).toLocaleString('en-IN')} km` : ''}</td></tr>`);
  }
  const td = 'style="padding:6px 10px;border-bottom:1px solid #e5e7eb"';
  const detail = [['Customer', r.customer_name], ['Product', `${product} (${r.category})`], ['Serial / VIN', r.serial_number],
    r.vehicle_reg_no ? ['Registration No.', r.vehicle_reg_no] : null, ['Invoice', r.invoice_number], ['Purchase date', fmtDate(r.purchase_date)],
    ['Standard warranty', `${r.warranty_months} months`], r.extended_warranty_months ? ['Extended warranty', `${r.extended_warranty_months} months`] : null,
    ['Warranty valid till', `<b>${fmtDate(r.warranty_end)}</b>`], ['Registration ID', r.registration_id]]
    .filter(Boolean).map(([k, v]) => `<tr><td ${td}><b>${esc(k)}</b></td><td ${td}>${String(v).startsWith('<b>') ? v : esc(v)}</td></tr>`).join('');
  const html = shell(s, `<div style="border:2px solid #0f766e;border-radius:10px;padding:18px">
<h2 style="color:#0f766e;margin-top:0">🛡️ Warranty Certificate</h2><p>Dear ${esc(r.first_name)}, thank you for choosing ${esc(s.dealer_name)}. Your product is now registered.</p>
<table style="border-collapse:collapse;width:100%;font-size:14px">${detail}</table>
${schedule.length ? `<h3>Your service schedule</h3><table style="font-size:14px">${schedule.join('')}</table><p style="font-size:13px;color:#6b7280">We'll remind you before every service. Servicing on time keeps your warranty healthy.</p>` : ''}
${button(s.booking_link, 'Book a service / support visit')}</div><p>Keep this email. Quote your Registration ID for warranty claims.</p>`);
  const sms = `Hi ${r.first_name}, your ${product} (S/N ${r.serial_number}) is registered with ${s.dealer_name}. Warranty valid till ${fmtDate(r.warranty_end)}.` +
    (r.next_service_date ? ` ${r.free_services_total ? 'First FREE service' : 'First service'} due ${fmtDate(r.next_service_date)}.` : '') + ` Book anytime: ${s.booking_link}`;
  const slug = v => String(v).toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  return { json: {
    row,
    contact_id: r.ghl_contact_id,
    tags: ['warranty-registered', `cat-${slug(r.category)}`, `brand-${slug(r.brand)}`, r.extended_warranty_months ? 'extended-warranty' : 'standard-warranty'],
    note: `🛡️ Warranty registered (${r.registration_id})\nProduct: ${product} | ${r.category}\nSerial/VIN: ${r.serial_number}${r.vehicle_reg_no ? ' | Reg: ' + r.vehicle_reg_no : ''}\nInvoice: ${r.invoice_number} | Purchased: ${r.purchase_date}\nWarranty till: ${r.warranty_end} (ext ${r.extended_warranty_months}m)\nNext service: ${r.next_service_date || 'n/a'}`,
    sms,
    email_subject: `Your warranty is registered: ${product}`,
    email_html: html,
  }, pairedItem: { item: i } };
});

// Decides which service / warranty reminder stage each product has reached today
const s = $('Set Reminder Config').first().json;
const DAY = 864e5;
const ist = new Date(Date.now() + 5.5 * 3600e3);
const today = Date.UTC(ist.getUTCFullYear(), ist.getUTCMonth(), ist.getUTCDate());
const dayOf = v => { const d = new Date(v); return isNaN(d) ? null : Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()); };
const offs = v => String(v).split(',').map(Number).filter(n => !isNaN(n));
const svcOffs = offs(s.service_offsets_days || '7,1,-7'), warOffs = offs(s.warranty_offsets_days || '60,30,7,-1');
const maxOver = Number(s.max_overdue_days) || 30;
const stageFor = (d, list) => { const hit = list.filter(o => d <= o); return hit.length ? Math.min(...hit) : null; };
const out = [];
for (const item of $('Get Warranty Registry').all()) {
  const r = item.json;
  if (!r.registration_id || !r.ghl_contact_id) continue;
  if (String(r.status || 'Active').toLowerCase() !== 'active') continue;
  const events = [];
  let svcMarker = String(r.service_reminder_stage || ''), warMarker = String(r.warranty_reminder_stage || '');

  const nsd = dayOf(r.next_service_date);
  if (Number(r.service_interval_months) > 0 && nsd !== null) {
    const d = Math.round((nsd - today) / DAY);
    const st = stageFor(d, svcOffs);
    const n = Number(r.next_service_number) || 1;
    const marker = `${n}:${st}`;
    if (st !== null && d >= -maxOver && marker !== svcMarker) {
      const firstInCycle = !svcMarker.startsWith(`${n}:`);
      const free = n <= (Number(r.free_services_total) || 0);
      events.push({ event_type: 'service', stage: st, days: d, service_number: n, is_free: free,
        label: d < 0 ? 'service_overdue' : d <= 1 ? 'service_due_now' : 'service_due_soon',
        est_value: free ? 0 : Number(r.est_service_value) || 0, first_in_cycle: firstInCycle,
        tags: [d < 0 ? 'service-overdue' : 'service-due', free ? 'free-service-due' : 'paid-service-due'],
        opp_name: `${free ? 'Free' : 'Paid'} service #${n} — ${r.brand} ${r.model} (${r.vehicle_reg_no || r.serial_number})`,
        opp_stage: s.ghl_stage_service_due });
      svcMarker = marker;
    }
  }
  const wend = dayOf(r.warranty_end);
  if (wend !== null) {
    const d = Math.round((wend - today) / DAY);
    const st = stageFor(d, warOffs);
    const marker = `W:${r.warranty_end}:${st}`;
    if (st !== null && d >= -15 && marker !== warMarker) {
      events.push({ event_type: 'warranty', stage: st, days: d,
        label: d < 0 ? 'warranty_expired' : 'warranty_expiring',
        est_value: Number(r.est_extended_value) || 0, first_in_cycle: !warMarker.startsWith(`W:${r.warranty_end}:`),
        tags: [d < 0 ? 'warranty-expired' : 'warranty-expiring', 'ew-amc-prospect'],
        opp_name: `${/car|wheeler/i.test(r.category) ? 'Extended warranty' : 'Extended warranty / AMC'} — ${r.brand} ${r.model} (${r.vehicle_reg_no || r.serial_number})`,
        opp_stage: s.ghl_stage_warranty_renewal });
      warMarker = marker;
    }
  }
  const tracker = { registration_id: r.registration_id, service_reminder_stage: svcMarker, warranty_reminder_stage: warMarker };
  for (const e of events) out.push({ json: {
    ...e, tracker, create_opportunity: e.first_in_cycle && e.est_value > 0,
    registration_id: r.registration_id, contact_id: r.ghl_contact_id, customer_name: r.customer_name,
    first_name: String(r.customer_name || '').split(' ')[0], category: r.category, brand: r.brand, model: r.model,
    serial_number: r.serial_number, vehicle_reg_no: r.vehicle_reg_no, warranty_end: r.warranty_end,
    next_service_date: r.next_service_date, service_interval_km: r.service_interval_km, last_odometer_km: r.last_odometer_km,
    dealer_name: s.dealer_name, booking_link: s.booking_link, current_offer: s.current_offer,
  }});
}
return out;

