const esc = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const fmtDate = v => { const d = new Date(v); return isNaN(d) ? '—' : d.toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'UTC' }); };
const ymd = d => d.toISOString().slice(0, 10);
const addMonths = (v, m) => { const d = new Date(v); if (isNaN(d)) return null; const day = d.getUTCDate(); const r = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth() + Number(m), 1)); const last = new Date(Date.UTC(r.getUTCFullYear(), r.getUTCMonth() + 1, 0)).getUTCDate(); r.setUTCDate(Math.min(day, last)); return r; };
const button = (url, label) => `<p style="margin:20px 0"><a href="${esc(url)}" style="background:#0f766e;color:#fff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold">${esc(label)}</a></p>`;
const shell = (s, inner) => `<div style="font-family:Arial,sans-serif;max-width:620px;color:#111827;line-height:1.5">${inner}<hr style="border:none;border-top:1px solid #e5e7eb;margin:24px 0"><p style="color:#6b7280;font-size:12px">${esc(s.dealer_name)} · ${esc(s.dealer_address)} · ${esc(s.dealer_phone)}</p></div>`;

const s = $('Set Reminder Config').first().json;
const plans = $('Plan Due Reminders').all();
return $input.all().map((item, i) => {
  const p = plans[i].json;
  let a = item.json.message?.content ?? item.json.content ?? {};
  if (typeof a === 'string') { try { a = JSON.parse(a.replace(/```json|```/g, '').trim()); } catch (e) { a = {}; } }
  const product = `${p.brand} ${p.model}`.trim();
  const fb = {
    service_due_soon: [`Hi ${p.first_name}, your ${product} is due for ${p.is_free ? 'its FREE ' : ''}service #${p.service_number} on ${fmtDate(p.next_service_date)}. Book a slot: ${p.booking_link} - ${s.dealer_name}`, `Service #${p.service_number} due for your ${product}`],
    service_due_now: [`Hi ${p.first_name}, service #${p.service_number} for your ${product} is due ${p.days === 0 ? 'today' : 'tomorrow'}. Pick a time: ${p.booking_link} - ${s.dealer_name}`, `Your ${product} service is due now`],
    service_overdue: [`Hi ${p.first_name}, service #${p.service_number} for your ${product} is ${Math.abs(p.days)} days overdue. Timely service keeps it running well. Book: ${p.booking_link} - ${s.dealer_name}`, `Service overdue: ${product}`],
    warranty_expiring: [`Hi ${p.first_name}, the warranty on your ${product} ends ${p.days === 0 ? 'today' : `on ${fmtDate(p.warranty_end)} (${p.days} days)`}. Extend your protection: ${p.booking_link} - ${s.dealer_name}`, p.days === 0 ? `Your ${product} warranty ends today` : `Your ${product} warranty ends in ${p.days} days`],
    warranty_expired: [`Hi ${p.first_name}, the warranty on your ${product} ended on ${fmtDate(p.warranty_end)}. Restore protection with an extended plan: ${p.booking_link} - ${s.dealer_name}`, `Restore protection for your ${product}`],
  }[p.label];
  let sms = a.sms || fb[0];
  if (!sms.includes(p.booking_link)) sms += ` ${p.booking_link}`;
  const paras = Array.isArray(a.email_paragraphs) && a.email_paragraphs.length ? a.email_paragraphs : [fb[0].split(' - ')[0]];
  const isW = p.event_type === 'warranty';
  const facts = isW
    ? `<p style="background:#f0fdfa;padding:10px 14px;border-radius:6px"><b>${esc(product)}</b> · S/N ${esc(p.serial_number)}<br>Warranty ${p.days < 0 ? 'ended' : 'ends'} on <b>${fmtDate(p.warranty_end)}</b></p>`
    : `<p style="background:#f0fdfa;padding:10px 14px;border-radius:6px"><b>${esc(product)}</b>${p.vehicle_reg_no ? ' · ' + esc(p.vehicle_reg_no) : ''}<br>Service #${p.service_number}${p.is_free ? ' <b style="color:#0f766e">(FREE)</b>' : ''} due <b>${fmtDate(p.next_service_date)}</b>${p.service_interval_km ? ` or at the ${Number(p.service_interval_km).toLocaleString('en-IN')} km interval` : ''}</p>`;
  const email_html = shell(s, `<p>Dear ${esc(p.first_name)},</p>${paras.map(x => `<p>${esc(x)}</p>`).join('')}${facts}
${button(s.booking_link, isW ? 'Talk to us about extended protection' : 'Book my service slot')}<p>Regards,<br>${esc(s.dealer_name)}</p>`);
  return { json: {
    registration_id: p.registration_id, contact_id: p.contact_id, event_type: p.event_type,
    create_opportunity: p.create_opportunity, tags: p.tags,
    sms, email_subject: a.email_subject || fb[1], email_html,
    note: `🔔 ${p.label.replace(/_/g, ' ')} reminder sent (stage ${p.stage}, ${p.days}d)\n${product} | ${p.vehicle_reg_no || p.serial_number}\nMessage: ${sms}`,
    stage_update: p.tracker,
    opportunity: { pipelineId: s.ghl_pipeline_id, locationId: s.ghl_location_id, pipelineStageId: p.opp_stage, name: p.opp_name,
                   status: 'open', contactId: p.contact_id, monetaryValue: p.est_value, source: 'After-sales automation' },
  }, pairedItem: { item: i } };
});

const c = $('Compose Reminder Messages').item.json;
const id = $json.opportunity?.id || $json.id || '';
const col = c.event_type === 'service' ? 'service_opportunity_id' : 'warranty_opportunity_id';
return { json: { registration_id: c.registration_id, [col]: id } };
